describe('Screen Reader Error Message Announcements', () => {
  beforeEach(() => {
    cy.visit('/error-page');
  });

  it('should announce error message when page loads with validation error', () => {
    cy.intercept('GET', '/api/validate-form').as('validationRequest');
    cy.wait('@validationRequest');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please fill all required fields');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-atomic', 'true');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-relevant', 'auto');
    cy.get('[data-testid="error-message"]').should('have.attr', 'role', 'alert');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-describedby', 'error-details');
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Field X is required');
    cy.get('[data-testid="error-details"]').should('contain', 'Field Y is required');
  });

  it('should announce error message when form submission fails due to validation', () => {
    cy.intercept('POST', '/api/submit-form', {
      statusCode: 400,
      body: { error: 'Validation failed' }
    }).as('formSubmission');

    cy.get('[data-testid="form-input-name"]').type('John Doe');
    cy.get('[data-testid="form-input-email"]').type('john@example.com');
    cy.get('[data-testid="form-input-password"]').type('password123');
    cy.get('[data-testid="form-submit-button"]').click();

    cy.wait('@formSubmission');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Validation failed');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-atomic', 'true');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-relevant', 'auto');
    cy.get('[data-testid="error-message"]').should('have.attr', 'role', 'alert');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-describedby', 'error-details');
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Email is invalid');
  });
});
